/*
 * Type regression test: axis `min`/`max` callbacks may return null/undefined
 * (documented "auto" behavior). Compile with tsc --noEmit.
 */
import { XAXisOption, YAXisOption } from '../../src/coord/cartesian/AxisModel';

const xAxis: XAXisOption = {
    type: 'value',
    min: (extent: {min: number, max: number}) => null,
    max: (extent: {min: number, max: number}) => undefined
};

const yAxis: YAXisOption = {
    type: 'value',
    min: (extent) => extent.min,
    max: () => null
};

export { xAxis, yAxis };
